Here's an example of how to use LINQ Touch to retrieve data from a user's social media profile:

```csharp
using System;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        // Create a new user
        var user = new User
        {
            Id = Guid.NewGuid(),
            Name = "John Doe",
            Email = "<EMAIL>",
            SocialMedia = new SocialMedia
            {
                Twitter = "https://twitter.com/JohnDoe",
                Facebook = "https://facebook.com/JohnDoe",
                Instagram = "https://instagram.com/JohnDoe"
            }
        };

        // Retrieve data from social media profiles
        var socialMedia = user.SocialMedia.Where(s => s.SocialMediaType == SocialMediaType.Twitter);
        Console.WriteLine($"Twitter: {socialMedia.Twitter}");
        Console.WriteLine($"Facebook: {socialMedia.Facebook}");
        Console.WriteLine($"Instagram: {socialMedia.Instagram}");
    }
}

// Define the social media types
enum SocialMediaType
{
    Twitter,
    Facebook,
    Instagram
}

// Define the user
class User
{
    public Guid Id { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
    public SocialMedia SocialMedia { get; set; }
}
```

